// Quick and Snappy Animationswindow.addEventListener('load', function(){// Add fade-in-up animation to elements const animateElements = document.querySelectorAll('.feature-card, .benefit-item, .team-member, .publication-card');animateElements.forEach((element, index) =>{// Stagger animations for a nice effect setTimeout(() =>{element.classList.add('animate-fade-in-up');}, index * 100);});});// Smooth scrolling for anchor links with snappy feeldocument.querySelectorAll('a[href^="#"]').forEach(anchor =>{anchor.addEventListener('click', function (e){e.preventDefault();document.querySelector(this.getAttribute('href')).scrollIntoView({ behavior: 'smooth'});});});// Add subtle scroll effect to headerwindow.addEventListener('scroll', function(){const header = document.querySelector('header');const backToTop = document.querySelector('.back-to-top');if (window.scrollY > 50){header.classList.add('scrolled');if (backToTop) backToTop.style.display = 'flex';} else{header.classList.remove('scrolled');if (backToTop) backToTop.style.display = 'none';}});// Back to top functionalitywindow.addEventListener('load', function(){const backToTop = document.createElement('button');backToTop.className = 'back-to-top';backToTop.innerHTML = '<i class="fas fa-arrow-up"></i>';backToTop.setAttribute('aria-label', 'Back to top');document.body.appendChild(backToTop);backToTop.addEventListener('click', function(){window.scrollTo({ top: 0, behavior: 'smooth'});});});// Add hover effects to interactive elementsconst addHoverEffects = function(){const buttons = document.querySelectorAll('button, .cta-button, .hero-cta-button, .feature-card, .team-member');buttons.forEach(button =>{button.addEventListener('mouseenter', function(){this.style.transform = 'translateY(-1px)';this.style.boxShadow = '0 4px 12px rgba(0, 0, 0, 0.1)';});button.addEventListener('mouseleave', function(){this.style.transform = 'translateY(0)';this.style.boxShadow = 'none';});});// Add keyboard navigation support const focusableElements = document.querySelectorAll('a[href], button, [tabindex="0"]');focusableElements.forEach(el =>{el.addEventListener('keydown', function(e){if (e.key === 'Enter' || e.key === ' '){e.preventDefault();this.click();}});});};// Initialize hover effects when DOM is readydocument.addEventListener('DOMContentLoaded', addHoverEffects);// Add touch support for mobile deviceswindow.addEventListener('load', function(){// Check if touch device const isTouchDevice = 'ontouchstart' in window || navigator.maxTouchPoints > 0;if (isTouchDevice){// Add touch-specific classes document.body.classList.add('touch-device');// Add touch feedback const touchElements = document.querySelectorAll('button, a, .feature-card, .team-member');touchElements.forEach(el =>{el.addEventListener('touchstart', function(){this.style.transform = 'scale(0.98)';this.style.transition = 'transform 0.1s ease';});el.addEventListener('touchend', function(){this.style.transform = 'scale(1)';});});}});